const refId = $json.refId || '';
const [epochMs, reporterChatId] = refId.split('|');
const timestampIso = new Date(Number(epochMs)).toISOString();
return [{ json: { ...$json, epochMs: Number(epochMs), reporterChatId, timestampIso } }];

const safe = (fn) => { try { return fn(); } catch (e) { return null; } };
const cb = safe(() => $('Code: Parse Callback Data').first().json);
const ai = safe(() => $('Code: Parse Output AI').first().json);

const orders  = $('Sheets: Get Orders (Validasi)').all().map(i => i.json).filter(o => o['ID Order']);
const logs    = $('Sheets: Get Log (Validasi)').all().map(i => i.json).filter(l => l['Order ID']);

let mode, chatId, reporterId, reporterName, jenis, jumlah, helper = '', orderId = '', karungAI = '';
if (cb) {
  mode = cb.action === 'pick' ? 'pick' : 'confirm';
  const p = String(cb.refId || '').split('|');
  jenis = p[0]; orderId = String(p[1] || '').trim(); jumlah = parseInt(p[2], 10);
  helper = (p[3] && p[3] !== '-') ? p[3] : '';
  chatId = cb.message.chat.id; reporterId = cb.from.id; reporterName = cb.from.first_name;
} else {
  mode = 'lapor';
  const msg = $('Telegram Trigger').first().json.message;
  const d = (ai && ai.data) || {};
  jenis = ai.intent === 'lapor_sablon' ? 's' : 'g';
  jumlah = parseInt(d.jumlah, 10);
  helper = jenis === 's' ? String(d.helper || '').trim() : '';
  karungAI = String(d.karung || '').trim();
  chatId = msg.chat.id; reporterId = msg.from.id; reporterName = msg.from.first_name;
}
helper = helper.replace(/[|:]/g, ' ').slice(0, 20).trim();

const jenisNama = jenis === 's' ? 'Sablon' : 'Gosok';
const targetKey = jenis === 's' ? 'Target Sablon' : 'Target Gosok';
const isAktif = s => String(s || '').trim().toLowerCase() === 'aktif';
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const fail = text => [{ json: { status: 'error', chatId, text } }];

const terpakai = id => logs
  .filter(l => String(l['Order ID']).trim() === id && String(l['Jenis Kerjaan']).trim().toLowerCase() === jenisNama.toLowerCase())
  .reduce((s, l) => s + (Number(l['Qty (bal)']) || 0), 0);

const all = orders.map(o => {
  const id = String(o['ID Order']).trim();
  const target = Number(o[targetKey]) || 0;
  const used = terpakai(id);
  return { orderId: id, karung: String(o['Jenis Karung'] || '').trim(),
           orderAktif: isAktif(o['Status']),
           target, used, sisa: target - used };
});
const open = all.filter(o => o.orderAktif && o.target > 0 && o.sisa > 0);

if (!(jumlah > 0)) return fail('Jumlah bal-nya belum kebaca 🙏 Coba tulis lagi, contoh: "8 bal urea sama ardi"');

const refOf = o => [jenis, o.orderId, jumlah, helper || '-'].join('|');
let order = null;

if (mode === 'lapor') {
  const k = norm(karungAI);
  const match = k ? open.filter(o => { const n = norm(o.karung); return n && (n.includes(k) || k.includes(n)); }) : [];
  let options = null, header = '';
  if (match.length === 1) {
    order = match[0];
  } else if (match.length > 1) {
    options = match;
    header = 'Ada ' + match.length + ' order ' + jenisNama + ' yang cocok. Laporan ' + jumlah + ' bal ini masuk ke order yang mana?';
  } else if (open.length > 0) {
    options = open;
    header = 'Order "' + (karungAI || '-') + '" tidak ditemukan atau sudah selesai untuk ' + jenisNama + '. Pilih order yang benar untuk laporan ' + jumlah + ' bal ini:';
  } else {
    return fail('Belum ada order aktif untuk ' + jenisNama + ', jadi laporan belum bisa dicatat. Hubungi Owner untuk membuat/mengaktifkan order dulu ya.');
  }
  if (options) {
    const rows = options.slice(0, 8).map(o => [{ text: o.karung + ' (sisa ' + o.sisa + ' bal)', callback_data: 'pick:x:' + refOf(o) }]);
    rows.push([{ text: 'Batal', callback_data: 'confirm:batal:-' }]);
    return [{ json: { status: 'pick', chatId, text: header, replyMarkup: { inline_keyboard: rows } } }];
  }
} else {
  order = all.find(o => o.orderId === orderId);
  if (!order) return fail('Order tidak ditemukan. Laporan dibatalkan, coba lapor ulang ya.');
  if (!order.orderAktif) return fail('Order ' + order.karung + ' sudah tidak aktif/selesai, jadi laporan tidak bisa dicatat.');
  if (order.target <= 0) return fail('Order ' + order.karung + ' tidak punya target ' + jenisNama + '.');
}

if (jumlah > order.sisa) {
  return fail('Jumlah ' + jumlah + ' bal melebihi sisa target ' + jenisNama + ' ' + order.karung + ', sisanya tinggal ' + Math.max(order.sisa, 0) + ' bal. Cek lagi jumlahnya ya.');
}

const detail = jenis === 's'
  ? 'Tukang: ' + reporterName + (helper ? ', Helper: ' + helper : '')
  : 'Penggosok: ' + reporterName;
const base = {
  chatId, jenisKerjaan: jenisNama, karung: order.karung, orderId: order.orderId,
  jumlah, helper, detail, sisaSebelum: order.sisa, sisaSetelah: order.sisa - jumlah,
  reporterTelegramId: reporterId, reporterChatId: reporterId
};

if (mode === 'confirm') {
  const epochMs = Date.now();
  return [{ json: { ...base, status: 'save',
    tukang: jenis === 's' ? reporterName : '', penggosok: jenis === 'g' ? reporterName : '',
    epochMs, timestamp: new Date(epochMs).toISOString() } }];
}
return [{ json: { ...base, status: 'confirm', refId: refOf(order) } }];

