const cb = $('Code: Parse RefId ACC').first().json;
const row = $('Sheets: Cari Baris Laporan').first().json;
const acc = cb.decision === 'acc';
const orderId = String(row['Order ID'] || '').trim();
const jenis = String(row['Jenis Kerjaan'] || '').trim();
const qty = Number(row['Qty (bal)']) || 0;
const orders = $('Sheets: Get Orders (Info Hasil)').all().map(i => i.json);
const logs = $('Sheets: Get Log (Info Hasil)').all().map(i => i.json);
const o = orders.find(x => String(x['ID Order'] || '').trim() === orderId) || {};
const karung = o['Jenis Karung'] || orderId;
const target = Number(o[jenis === 'Sablon' ? 'Target Sablon' : 'Target Gosok']) || 0;
const used = logs
  .filter(l => String(l['Order ID'] || '').trim() === orderId && String(l['Jenis Kerjaan'] || '').trim().toLowerCase() === jenis.toLowerCase())
  .reduce((s, l) => s + (Number(l['Qty (bal)']) || 0), 0);
const sisa = target - used;
const orang = jenis === 'Sablon'
  ? 'Tukang: ' + (row['Tukang'] || '-') + (row['Helper'] ? ', Helper: ' + row['Helper'] : '')
  : 'Penggosok: ' + (row['Penggosok'] || '-');
const ringkas = jenis + ' ' + qty + ' bal ' + karung + '\n' + orang;
const sisaTxt = 'Sisa target ' + jenis + ' ' + karung + ': ' + sisa + ' bal';
const ownerText = acc
  ? '✅ Laporan disetujui (ACC)\n' + ringkas + '\n' + sisaTxt
  : '❌ Laporan ditolak & dihapus\n' + ringkas + '\nTarget dikembalikan. ' + sisaTxt;
const workerText = acc
  ? 'Tersimpan & disetujui! ✅\n' + ringkas + '\n' + sisaTxt
  : 'Maaf, laporanmu ditolak Owner ❌\n' + ringkas + '\nTarget dikembalikan. ' + sisaTxt;
return [{ json: { ownerChatId: cb.from.id, workerChatId: cb.reporterChatId, ownerText, workerText } }];

const tz='Asia/Makassar';
const now=new Date();
const tgl=now.toLocaleString('id-ID',{timeZone:tz,dateStyle:'full',timeStyle:'short'});
const tabel=(items)=>{
  const rows=items.map(i=>i.json).filter(r=>Object.values(r).some(v=>String(v||'').trim()!==''));
  if(!rows.length) return '(kosong)';
  const cols=Object.keys(rows[0]).filter(c=>c!=='row_number');
  return cols.join(' | ')+'\n'+rows.map(r=>cols.map(c=>String(r[c]??'').replace(/\s+/g,' ')).join(' | ')).join('\n');
};
const safe=(n)=>{try{return $(n).all();}catch(e){return [];}};
const HEAD='\nKOLOM SHEET YANG BOLEH DIUBAH:\n- Order: ID Order | Jenis Karung | Target Sablon | Target Gosok | Status (Aktif/Selesai) | Tanggal Dibuat\n- Detail Log: Timestamp | Order ID | Jenis Kerjaan (Sablon/Gosok) | Qty (bal) | Tukang | Helper | Penggosok | Dilaporkan oleh (Telegram User ID) | Status (Pending/Approved)\n- User: lihat kolom di tabel DAFTAR PENGGUNA\n(Sheet Ringkasan dihitung otomatis dari Detail Log, jangan ditulis.)';
const pertanyaan=$('Telegram Trigger').first().json.message.text;
const konteks=[
 'SEKARANG: '+tgl+' (zona WITA)',
 '\n## ORDER (kolom Tanggal Dibuat = kapan order dibuat)\n'+tabel(safe('Sheets: Get Active Orders')),
 '\n## RINGKASAN (target, realisasi, sisa per order)\n'+tabel(safe('Sheets: Read Ringkasan')),
 '\n## DETAIL LOG (semua laporan; Timestamp format ISO UTC; Status Pending/Approved)\n'+tabel(safe('Sheets: Read Detail Log')),
 '\n## DAFTAR PENGGUNA (nama, status)\n'+tabel(safe('Sheets: Get Users List'))
,HEAD].join('\n');
return [{json:{pertanyaan,konteks}}];

const raw=String($input.first().json.output||'');
const msg=$('Telegram Trigger').first().json.message;
const chatId=msg.chat.id, ownerId=msg.from.id, ownerName=msg.from.first_name||'Owner';
let p;
try{ const m=raw.match(/\{[\s\S]*\}/); p=JSON.parse(m?m[0]:raw); }catch(e){ p={tipe:'jawab',teks:raw}; }
const out=(mode,text,extra={})=>[{json:{mode,chatId,text:String(text||'').slice(0,3900),...extra}}];
if(p.tipe!=='usulan') return out('jawab',p.teks||raw||'Maaf, aku belum bisa menjawab itu.');

const rowsOf=n=>{try{return $(n).all().map(i=>i.json).filter(r=>Object.values(r).some(v=>String(v||'').trim()!==''));}catch(e){return [];}};
const DATA={'Order':rowsOf('Sheets: Get Active Orders'),'User':rowsOf('Sheets: Get Users List'),'Detail Log':rowsOf('Sheets: Read Detail Log')};
const userHead=DATA.User.length?Object.keys(DATA.User[0]).filter(c=>c!=='row_number'):['Telegram User ID','Nama','Status','Role'];
const HEAD={'Order':['ID Order','Jenis Karung','Target Sablon','Target Gosok','Status','Tanggal Dibuat'],
 'Detail Log':['Timestamp','Order ID','Jenis Kerjaan','Qty (bal)','Tukang','Helper','Penggosok','Dilaporkan oleh (Telegram User ID)','Status'],'User':userHead};
const a=p.aksi||{}; const op=String(a.op||'').toLowerCase().trim(); const sheet=a.sheet;
const cocok=a.cocok&&typeof a.cocok==='object'?a.cocok:{}; let data=a.data&&typeof a.data==='object'?{...a.data}:{};
if(!HEAD[sheet]) return out('jawab','Sheet yang dimaksud belum jelas. Mau ubah Order, User, atau Detail Log?');
if(!['tambah','ubah','hapus'].includes(op)) return out('jawab','Mau ditambah, diubah, atau dihapus?');
const head=HEAD[sheet];
const salah=[...Object.keys(cocok),...Object.keys(data)].filter(c=>!head.includes(c));
if(salah.length) return out('jawab','Kolom "'+salah.join(', ')+'" tidak ada di sheet '+sheet+'. Kolom yang ada: '+head.join(', ')+'.');
if('Role' in data) return out('jawab','Kolom Role tidak bisa diubah lewat chat. Ubah manual di Google Sheet ya.');
const norm=s=>String(s??'').trim().toLowerCase();
const now=new Date(); const wita=new Date(now.getTime()+8*3600*1000);
let cocokRow=null; let teksPreview='';
if(op==='tambah'){
  if(sheet==='Order'){
    if(!data['ID Order']){let max=0;DATA.Order.forEach(o=>{const m=String(o['ID Order']).match(/(\d+)$/);if(m)max=Math.max(max,+m[1]);});data['ID Order']='ORD-'+String(max+1).padStart(3,'0');}
    if(!data['Status'])data['Status']='Aktif';
    if(!data['Tanggal Dibuat'])data['Tanggal Dibuat']=wita.toISOString().slice(0,10);
    const dup=DATA.Order.find(o=>norm(o['Jenis Karung'])===norm(data['Jenis Karung'])&&norm(o['Status'])==='aktif'&&norm(data['Status'])==='aktif');
    if(dup) return out('jawab','Order '+dup['Jenis Karung']+' masih Aktif (ID '+dup['ID Order']+'). Tutup dulu, atau mau tetap dibuat order baru?');
    var wajib=['Jenis Karung','Target Sablon','Target Gosok'];
  } else if(sheet==='Detail Log'){
    if(!data['Timestamp'])data['Timestamp']=now.toISOString();
    if(!data['Status'])data['Status']='Approved';
    if(!data['Dilaporkan oleh (Telegram User ID)'])data['Dilaporkan oleh (Telegram User ID)']=String(ownerId);
    var wajib=['Order ID','Jenis Kerjaan','Qty (bal)'];
  } else { var wajib=['Telegram User ID','Nama','Status']; }
  const kurang=wajib.filter(c=>head.includes(c)&&norm(data[c])==='');
  if(kurang.length) return out('jawab','Datanya belum lengkap. Tolong isi dulu: '+kurang.join(', ')+'.');
  teksPreview='➕ TAMBAH data baru ke sheet '+sheet+':\n'+Object.entries(data).map(([k,v])=>'• '+k+': '+v).join('\n');
