// Cari order yang mau ditutup SECARA OTOMATIS (tanpa bergantung pada tebakan AI)
const ai = $('Code: Parse Output AI').first().json;
const msg = $('Telegram Trigger').first().json.message || {};
const chatId = msg.chat.id;
const text = String(msg.text || '');

// Data order sudah dibaca di awal alur (Sheets: Get Active Orders) -> tidak perlu baca Sheets lagi
const orders = $('Sheets: Get Active Orders').all().map(i => i.json).filter(o => o['ID Order']);
const isAktif = s => String(s || '').trim().toLowerCase() === 'aktif';
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const fail = t => [{ json: { ok: false, chatId, text: t } }];
const aktif = orders.filter(o => isAktif(o['Status']));
const daftar = aktif.map(o => '- ' + o['ID Order'] + ' (' + o['Jenis Karung'] + ')').join('\n');

if (!aktif.length) return fail('Tidak ada order aktif yang bisa ditutup.');

let target = null;

// 1) Ada ID order di pesan (ORD-001 / ord 1 / ord001)
const idMatch = text.match(/ORD[-\s]?0*(\d+)/i);
if (idMatch) {
  const num = parseInt(idMatch[1], 10);
  const found = orders.find(o => { const m = String(o['ID Order']).match(/(\d+)$/); return m && parseInt(m[1], 10) === num; });
  if (!found) return fail('Order ORD-' + String(num).padStart(3, '0') + ' tidak ditemukan.\nOrder aktif:\n' + daftar);
  if (!isAktif(found['Status'])) return fail('Order ' + found['ID Order'] + ' (' + found['Jenis Karung'] + ') sudah tidak aktif.');
  target = found;
} else {
  // 2) Tidak ada ID -> cocokkan lewat nama karung dari AI
  const k = norm((ai.data || {}).jenis_karung);
  if (k) {
    const m = aktif.filter(o => { const n = norm(o['Jenis Karung']); return n && (n.includes(k) || k.includes(n)); });
    if (m.length === 1) target = m[0];
    else if (m.length > 1) return fail('Ada beberapa order aktif yang cocok. Sebutkan ID-nya, contoh: "selesaikan ' + m[0]['ID Order'] + '"\n' + m.map(o => '- ' + o['ID Order'] + ' (' + o['Jenis Karung'] + ')').join('\n'));
  } else if (aktif.length === 1) {
    // 3) Tidak menyebut apa pun tapi cuma ada 1 order aktif -> tutup order itu
    target = aktif[0];
  }
  if (!target) return fail('Order mana yang mau ditutup? Order aktif:\n' + daftar + '\nContoh: "selesaikan ' + aktif[0]['ID Order'] + '"');
}

return [{ json: { ok: true, chatId, idOrder: String(target['ID Order']).trim(), jenisKarung: String(target['Jenis Karung'] || '').trim() } }];
